import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void tanh_kernel_vec4(const float4* __restrict__ in, float4* __restrict__ out, int64_t n4) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    for (int64_t i = idx; i < n4; i += stride) {
        float4 v = in[i];
        float4 r;
        r.x = tanhf(v.x);
        r.y = tanhf(v.y);
        r.z = tanhf(v.z);
        r.w = tanhf(v.w);
        out[i] = r;
    }
}

__global__ void tanh_kernel_scalar(const float* __restrict__ in, float* __restrict__ out, int64_t n) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    for (int64_t i = idx; i < n; i += stride) {
        out[i] = tanhf(in[i]);
    }
}

torch::Tensor tanh_cuda(torch::Tensor x) {
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);
    int64_t n = x_contig.numel();

    const int threads = 256;

    if (n % 4 == 0) {
        int64_t n4 = n / 4;
        int blocks = (int)((n4 + threads - 1) / threads);
        if (blocks > 65535) blocks = 65535;
        if (blocks < 1) blocks = 1;
        tanh_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(x_contig.data_ptr<float>()),
            reinterpret_cast<float4*>(out.data_ptr<float>()),
            n4
        );
    } else {
        int blocks = (int)((n + threads - 1) / threads);
        if (blocks > 65535) blocks = 65535;
        if (blocks < 1) blocks = 1;
        tanh_kernel_scalar<<<blocks, threads>>>(
            x_contig.data_ptr<float>(),
            out.data_ptr<float>(),
            n
        );
    }

    return out;
}
"""

cpp_source = "torch::Tensor tanh_cuda(torch::Tensor x);"

tanh_module = load_inline(
    name="tanh_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["tanh_cuda"],
    extra_cuda_cflags=["-use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a Tanh activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.tanh_op = tanh_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.tanh_op.tanh_cuda(x)


batch_size = 4096
dim = 131072


def get_inputs():
    x = torch.rand(batch_size, dim)
    return [x]


def get_init_inputs():
    return []

